import time
import adafruit_dht
import RPi.GPIO as GPIO

# GPIO pins wired to the DHT22 sensors (BCM numbering)
DHT_PINS = [4, 5, 17, 23]

def read_dht22(sensor_pin):
    """Read one DHT22 sensor and return temperature and humidity."""
    # Create the DHT device with a retry counter
    dht_device = adafruit_dht.DHT22(sensor_pin, use_pulseio=False)
    max_retries = 5
    for attempt_index in range(max_retries):
        try:
            temperature_c = dht_device.temperature
            humidity_percent = dht_device.humidity
            if temperature_c is not None and humidity_percent is not None:
                # Basic validity check for the reading
                if -40 <= temperature_c <= 80 and 0 <= humidity_percent <= 100:
                    return temperature_c, humidity_percent
                print("DHT22 reading out of range")
            time.sleep(1)
        except RuntimeError as error:
            # Sensor did not respond, retry
            print("DHT22 read error:", error)
            time.sleep(1)
    print("DHT22 read failed after", max_retries, "attempts")
    return None, None

def main():
    """Poll all DHT22 sensors and report their states."""
    # Configure the GPIO pins
    GPIO.setmode(GPIO.BCM)
    for sensor_pin in DHT_PINS:
        GPIO.setup(sensor_pin, GPIO.IN)
    try:
        while True:
            for sensor_pin in DHT_PINS:
                temperature_c, humidity_percent = read_dht22(sensor_pin)
                if temperature_c is not None and humidity_percent is not None:
                    print("Sensor on pin", sensor_pin, "temp", round(temperature_c, 1), "C, humidity", round(humidity_percent, 1), "%")
                else:
                    print("Sensor on pin", sensor_pin, "unreadable")
            time.sleep(60)
    except KeyboardInterrupt:
        print("Stopping DHT22 monitor")
    finally:
        # Release the GPIO pins
        GPIO.cleanup()

if __name__ == "__main__":
    main()

