import time
import board
import adafruit_dht
import RPi.GPIO as GPIO

# Define DHT sensors using BCM pin numbering
DHT_SENSORS = [
    {'pin': board.D4, 'sensor_id': 'dht22_1'},
    {'pin': board.D17, 'sensor_id': 'dht22_2'},
    {'pin': board.D27, 'sensor_id': 'dht22_3'}
]

def initialize_dht_sensors(sensor_configs):
    """Initialize DHT sensors and return a list of sensor objects."""
    dht_devices = []
    for config in sensor_configs:
        try:
            dht_device = adafruit_dht.DHT22(config['pin'])
            dht_devices.append({'sensor': dht_device, 'id': config['sensor_id']})
        except Exception as e:
            print(f"Error initializing DHT sensor on pin {config['pin']}: {e}")
    return dht_devices

def read_dht_data(dht_devices):
    """Read temperature and humidity from all configured DHT sensors."""
    sensor_data = {}
    for device in dht_devices:
        try:
            temperature_c = device['sensor'].temperature
            humidity = device['sensor'].humidity
            sensor_data[device['id']] = (temperature_c, humidity)
        except RuntimeError as e:
            print(f"DHT {device['id']} read error: {e}")
        except Exception as e:
            print(f"Unexpected error reading DHT {device['id']}: {e}")
    return sensor_data

def display_sensor_data(data):
    """Print the temperature and humidity readings for each sensor."""
    for sensor_id, (temperature_c, humidity) in data.items():
        if temperature_c is not None and humidity is not None:
            print(f"Sensor {sensor_id}: Temperature = {temperature_c:.1f}°C, Humidity = {humidity:.1f}%")
        else:
            print(f"Sensor {sensor_id}: Failed to read data.")

def main():
    """Main function to read and display DHT sensor data."""
    try:
        # Initialize DHT sensors
        dht_sensors = initialize_dht_sensors(DHT_SENSORS)
        if not dht_sensors:
            print("No DHT sensors initialized. Exiting.")
            return

        # Continuously read and display sensor data
        while True:
            sensor_data = read_dht_data(dht_sensors)
            display_sensor_data(sensor_data)
            time.sleep(1)

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean up GPIO settings
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

# serial data exchange for a Raspberry Pi using pyserial
# Reads data from a connected device over a serial port
import serial
import time

# Serial port configuration for the Raspberry Pi
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT_SECONDS = 1


def open_serial_port(port_name, baud_rate, timeout_seconds):
    """Open and return a serial port for communication."""
    # Configure the serial port for the Raspberry Pi
    serial_connection = serial.Serial(
        port=port_name, baudrate=baud_rate, timeout=timeout_seconds
    )
    return serial_connection


def read_one_line(serial_connection):
    """Read one decoded line from the serial port, or None if empty."""
    # Read one line and strip whitespace from the device
    raw_line = serial_connection.readline()
    if not raw_line:
        return None
    return raw_line.decode("utf-8", errors="ignore").strip()


def is_valid_reading(reading_text):
    """Return True when the reading text is not empty."""
    # Avoid accepting empty or malformed readings
    return reading_text and reading_text[0].isalpha()


if __name__ == "__main__":
    # Exchange data with a serial device on the Raspberry Pi
    serial_connection = None
    try:
        serial_connection = open_serial_port(
            SERIAL_PORT, BAUD_RATE, TIMEOUT_SECONDS
        )
        while True:
            # Read one line and print it if valid
            reading_text = read_one_line(serial_connection)
            if reading_text and is_valid_reading(reading_text):
                print("Received:", reading_text)
            time.sleep(0.1)
    except KeyboardInterrupt:
        # Stop the loop when interrupted
        print("Stopping serial exchange")
    finally:
        # Always close the serial port
        if serial_connection is not None:
            serial_connection.close()

# Ultrasonic distance sensors for wildlife tracking using Raspberry Pi
# Reads multiple HC-SR04 sensors through gpiozero and reports distances
from gpiozero import DistanceSensor
import time
import signal
import sys

# BCM pin assignments for the ultrasonic sensors
SENSOR_PINS = {
    "sensor1": 5,
    "sensor2": 6,
    "sensor3": 17,
    "sensor4": 18,
    "sensor5": 22,
    "sensor6": 23,
    "sensor7": 24,
    "sensor8": 27,
}

# Shared list to hold sensor readings for the wildlife tracker
distance_readings = {}


def read_distance(sensor_name, sensor_device):
    """Read a distance in centimeters from one ultrasonic sensor."""
    # Measure the distance and store the reading
    try:
        distance_cm = sensor_device.distance * 100
        distance_readings[sensor_name] = round(distance_cm, 1)
    except Exception:
        # Handle a failed measurement gracefully
        distance_readings[sensor_name] = None


def report_distances():
    """Print the current set of ultrasonic sensor readings."""
    # Loop through each sensor and print its distance
    for sensor_name, distance_value in distance_readings.items():
        print(sensor_name, "->", distance_value, "cm")


def main():
    """Create sensors and continuously poll them for wildlife tracking."""
    # Build a gpiozero DistanceSensor for each configured pin
    sensors = {
        sensor_name: DistanceSensor(pin_number, max_distance=2.0)
        for sensor_name, pin_number in SENSOR_PINS.items()
    }
    try:
        # Continuously poll each sensor and report its distance
        while True:
            for sensor_name, sensor_device in sensors.items():
                read_distance(sensor_name, sensor_device)
            report_distances()
            time.sleep(1)
    except KeyboardInterrupt:
        # Allow the field operator to stop the tracker
        print("Wildlife tracking stopped")
    finally:
        # Release all gpiozero devices on exit
        for sensor_device in sensors.values():
            sensor_device.close()


if __name__ == "__main__":
    main()
